  "code": "def read_stations(name):\n    stations = {}\n    with open(name) as f:\n        f.readline()\n        for line in f:\n            sid, sname, capacity = line.strip().split(\";\")\n            stations[sid] = sname\n    return stations\n\n\ndef read_trips(name):\n    trips = []\n    with open(name) as f:\n        f.readline()\n        for line in f:\n            bike, start, end, minutes = line.strip().split(\";\")\n            trips.append((bike, start, end, int(minutes)))\n    return trips\n\n\ndef main():\n    stations = read_stations(\"stations.csv\")\n    trips = read_trips(\"trips.csv\")\n    print(\"Stations:\", len(stations))\n    print(\"Trips:\", len(trips))\n    dep = {s: 0 for s in stations}\n    arr = {s: 0 for s in stations}\n    total = {s: 0 for s in stations}\n    bikes = {}\n    for bike, start, end, minutes in trips:\n        dep[start] += 1\n        arr[end] += 1\n        total[start] += minutes\n        bikes[bike] = bikes.get(bike, 0) + minutes\n    for s in stations:\n        avg = f\"{total[s] / dep[s]:.1f}\" if dep[s] > 0 else \"-\"\n        print(f\"{stations[s]}: {dep[s]} departures, {arr[s]} arrivals, average {avg} min\")\n    loser = max(stations, key=lambda s: dep[s] - arr[s])\n    print(f\"Station losing most bikes: {stations[loser]} ({dep[loser] - arr[loser]})\")\n    best = max(bikes, key=lambda b: bikes[b])\n    print(f\"Bike with most minutes: {best} ({bikes[best]} min)\")\n\n\nmain()"
