  "code": "def to_minutes(hhmm):\n    h, m = hhmm.split(\":\")\n    return int(h) * 60 + int(m)\n\n\ndef cost(minutes):\n    hours = (minutes + 59) // 60\n    return max(hours, 1) * 1.50\n\n\ndef main():\n    inside = {}\n    total = 0.0\n    current = 0\n    peak, peak_time = 0, \"\"\n    with open(\"log.txt\") as f:\n        for line in f:\n            plate, time, event = line.split()\n            if event == \"IN\":\n                inside[plate] = to_minutes(time)\n                current += 1\n                if current > peak:\n                    peak, peak_time = current, time\n            else:\n                minutes = to_minutes(time) - inside.pop(plate)\n                current -= 1\n                c = cost(minutes)\n                total += c\n                print(f\"{plate}: {minutes} min, {c:.2f} EUR\")\n    print(f\"Total revenue: {total:.2f} EUR\")\n    print(\"Still inside:\", \", \".join(sorted(inside)))\n    print(f\"Most cars inside at the same time: {peak} (first at {peak_time})\")\n\n\nmain()"
