  "out": "Water level: 3\n5 6 7 8 8 7 6 5\n4 ~ ~ 5 9 6 4 ~\n~ ~ ~ ~ 6 4 ~ ~\n4 ~ ~ ~ ~ ~ ~ 4\n6 4 ~ ~ 5 7 6 6\n7 6 5 4 6 8 9 7\nFlooded: 17 of 48 cells (35.4%)\nMost flooded row: 3 (6 cells)\nHighest dry cell: 9 at row 2, column 5",
  "code": "def read_map(name):\n    grid = []\n    with open(name) as f:\n        for line in f:\n            if line.strip():\n                grid.append([int(x) for x in line.split()])\n    return grid\n\n\ndef main():\n    grid = read_map(\"map.txt\")\n    level = int(input(\"Water level: \"))\n    flooded = 0\n    best_row, best_count = 0, -1\n    high, high_pos = -1, None\n    for i, row in enumerate(grid):\n        count = 0\n        cells = []\n        for j, h in enumerate(row):\n            if h <= level:\n                cells.append(\"~\")\n                count += 1\n            else:\n                cells.append(str(h))\n                if h > high:\n                    high, high_pos = h, (i + 1, j + 1)\n        print(\" \".join(cells))\n        flooded += count\n        if count > best_count:\n            best_row, best_count = i + 1, count\n    total = len(grid) * len(grid[0])\n    print(f\"Flooded: {flooded} of {total} cells ({100 * flooded / total:.1f}%)\")\n    print(f\"Most flooded row: {best_row} ({best_count} cells)\")\n    if high_pos:\n        print(f\"Highest dry cell: {high} at row {high_pos[0]}, column {high_pos[1]}\")\n    else:\n        print(\"Everything is flooded\")\n\n\nmain()"
