  "out": "T1: 6 valid, min 28.5, max 32.6, average 30.6, errors 0\nT2: 5 valid, min 31.0, max 34.1, average 32.4, errors 1\nT3: 3 valid, min 26.1, max 30.2, average 27.9, errors 3\n\nT1: longest run above 30.0 = 3 readings (from 09:00)\nT2: longest run above 30.0 = 3 readings (from 11:00)\nT3: longest run above 30.0 = 1 readings (from 12:00)\n\nMost errors: T3 (3)",
  "code": "LIMIT = 30.0\n\n\ndef read_data(name):\n    data = {}\n    with open(name) as f:\n        for line in f:\n            sensor, time, value = line.strip().split(\";\")\n            data.setdefault(sensor, []).append((time, value))\n    return data\n\n\ndef longest_run(readings):\n    best, best_start = 0, \"-\"\n    run, start = 0, \"\"\n    for time, value in readings:\n        if value != \"ERR\" and float(value) > LIMIT:\n            if run == 0:\n                start = time\n            run += 1\n            if run > best:\n                best, best_start = run, start\n        else:\n            run = 0\n    return best, best_start\n\n\ndef main():\n    data = read_data(\"readings.txt\")\n    worst, worst_err = None, -1\n    for sensor in sorted(data):\n        values = [float(v) for t, v in data[sensor] if v != \"ERR\"]\n        errors = len(data[sensor]) - len(values)\n        print(f\"{sensor}: {len(values)} valid, min {min(values)}, max {max(values)}, \"\n              f\"average {sum(values) / len(values):.1f}, errors {errors}\")\n        if errors > worst_err:\n            worst, worst_err = sensor, errors\n    print()\n    for sensor in sorted(data):\n        n, start = longest_run(data[sensor])\n        print(f\"{sensor}: longest run above {LIMIT} = {n} readings (from {start})\")\n    print()\n    print(f\"Most errors: {worst} ({worst_err})\")\n\n\nmain()"
