  "out": "Matches: 12, goals: 28, average 2.33 per match\nTeam      P  W  D  L  GF  GA  Pts\nLions     5  3  2  0   9   4   11\nEagles    5  1  4  0   6   5    7\nSharks    5  1  2  2   3   6    5\nTigers    4  1  1  2   6   6    4\nWolves    5  1  1  3   4   7    4\nBest defence: Lions (4 goals conceded)",
  "code": "def new_team():\n    return {\"P\": 0, \"W\": 0, \"D\": 0, \"L\": 0, \"GF\": 0, \"GA\": 0, \"Pts\": 0}\n\n\ndef add_result(t, scored, conceded):\n    t[\"P\"] += 1\n    t[\"GF\"] += scored\n    t[\"GA\"] += conceded\n    if scored > conceded:\n        t[\"W\"] += 1\n        t[\"Pts\"] += 3\n    elif scored == conceded:\n        t[\"D\"] += 1\n        t[\"Pts\"] += 1\n    else:\n        t[\"L\"] += 1\n\n\ndef main():\n    teams = {}\n    matches = goals = 0\n    with open(\"matches.txt\") as f:\n        for line in f:\n            home, away, gh, ga = line.strip().split(\";\")\n            gh, ga = int(gh), int(ga)\n            matches += 1\n            goals += gh + ga\n            add_result(teams.setdefault(home, new_team()), gh, ga)\n            add_result(teams.setdefault(away, new_team()), ga, gh)\n    print(f\"Matches: {matches}, goals: {goals}, average {goals / matches:.2f} per match\")\n    order = sorted(teams, key=lambda n: (-teams[n][\"Pts\"], -(teams[n][\"GF\"] - teams[n][\"GA\"]), n))\n    print(f\"{'Team':<8}{'P':>3}{'W':>3}{'D':>3}{'L':>3}{'GF':>4}{'GA':>4}{'Pts':>5}\")\n    for n in order:\n        t = teams[n]\n        print(f\"{n:<8}{t['P']:>3}{t['W']:>3}{t['D']:>3}{t['L']:>3}{t['GF']:>4}{t['GA']:>4}{t['Pts']:>5}\")\n    best = min(sorted(teams), key=lambda n: teams[n][\"GA\"])\n    print(f\"Best defence: {best} ({teams[best]['GA']} goals conceded)\")\n\n\nmain()"
